"use strict";(self.webpackChunkwebsite=self.webpackChunkwebsite||[]).push([[2771],{60979:(e,t,n)=>{n.r(t),n.d(t,{assets:()=>c,contentTitle:()=>r,default:()=>d,frontMatter:()=>o,metadata:()=>i,toc:()=>h});const i=JSON.parse('{"id":"cartesi-machine/intro","title":"Introduction","description":"The Cartesi Machine is Cartesi\'s solution for verifiable computation.","source":"@site/docs/cartesi-machine/index.md","sourceDirName":"cartesi-machine","slug":"/cartesi-machine/","permalink":"/docs/pr-preview/pr-303/cartesi-machine/","draft":false,"unlisted":false,"editUrl":"https://github.com/cartesi/docs/tree/develop/docs/cartesi-machine/index.md","tags":[],"version":"current","lastUpdatedAt":1783201846000,"frontMatter":{"title":"Introduction","id":"intro"},"sidebar":"machine","next":{"title":"Overview","permalink":"/docs/pr-preview/pr-303/cartesi-machine/host/"}}');var a=n(74848),s=n(28453);const o={title:"Introduction",id:"intro"},r=void 0,c={},h=[{value:"Scalability",id:"scalability",level:2},{value:"Productivity",id:"productivity",level:2},{value:"What&#39;s in a machine",id:"whats-in-a-machine",level:2},{value:"Rolling Cartesi Machines and Cartesi Rollups",id:"rolling-cartesi-machines-and-cartesi-rollups",level:3},{value:"Documentation",id:"documentation",level:2}];function l(e){const t={a:"a",code:"code",em:"em",h2:"h2",h3:"h3",li:"li",p:"p",ul:"ul",...(0,s.R)(),...e.components};return(0,a.jsxs)(a.Fragment,{children:[(0,a.jsx)(t.p,{children:"The Cartesi Machine is Cartesi's solution for verifiable computation.\nIt was designed to bring mainstream scalability to dApps and mainstream productivity to dApp developers."}),"\n",(0,a.jsx)(t.h2,{id:"scalability",children:"Scalability"}),"\n",(0,a.jsx)(t.p,{children:"dApps running exclusively on smart contracts face severe constraints on the amount of data they can manipulate and on the complexity of computations they can perform.\nThese limitations manifest themselves as exorbitant transaction costs and, even if such costs could somehow be overcome, as extremely long computation times."}),"\n",(0,a.jsx)(t.p,{children:"In comparison, dApps running inside Cartesi Machines can process relatively unlimited amounts of data, and at a pace over 4 orders of magnitude faster.\nThis is possible because Cartesi Machines run off-chain, free of the overhead imposed by the consensus mechanisms used by blockchains."}),"\n",(0,a.jsx)(t.p,{children:"In a typical scenario, one of the parties involved in a dApp will execute the Cartesi Machine off-chain and report its results to the blockchain.\nDifferent parties do not need to trust each other because the Cartesi platform includes an automatic dispute mechanism for Cartesi Machines.\nAll interested parties repeat the computation off-chain and, if their results do not agree, they enter into a dispute, which the mechanism guarantees to be always won by an honest party against any dishonest party."}),"\n",(0,a.jsx)(t.p,{children:"To enable this dispute mechanism, Cartesi Machines are executed inside a special emulator that has three unique properties:"}),"\n",(0,a.jsxs)(t.ul,{children:["\n",(0,a.jsxs)(t.li,{children:["Cartesi Machines are ",(0,a.jsx)(t.em,{children:"self contained"})," \u2014 They run in isolation from any external influence on the computation;"]}),"\n",(0,a.jsxs)(t.li,{children:["Cartesi Machines are ",(0,a.jsx)(t.em,{children:"reproducible"})," \u2014 Two parties performing the same computation always obtain exactly the same results;"]}),"\n",(0,a.jsxs)(t.li,{children:["Cartesi Machines are ",(0,a.jsx)(t.em,{children:"transparent"})," \u2014 They expose their entire state for external inspection."]}),"\n"]}),"\n",(0,a.jsx)(t.p,{children:"From the point of view of the blockchain, the disputes require only a tiny fraction of the amount of computation performed by the Cartesi Machine.\nDispute resolution thus becomes an ordinary task and dishonest parties are generally expected to be exposed, which discourages the posting of incorrect results and further increases the efficiency of the platform."}),"\n",(0,a.jsx)(t.p,{children:"Cartesi Machines allow dApps to take advantage of vastly increased computing capabilities off-chain, while enjoying the same security guarantees offered by code that runs natively as smart contracts.\nThis is what Cartesi means by scalability."}),"\n",(0,a.jsx)(t.h2,{id:"productivity",children:"Productivity"}),"\n",(0,a.jsx)(t.p,{children:"Scalability is not the only impediment to widespread blockchain adoption.\nAnother serious limiting factor is the reduced developer productivity."}),"\n",(0,a.jsx)(t.p,{children:"Modern software development involves the combination of dozens of off-the-shelf software components.\nCreating these components took the concerted effort of an active worldwide community over the course of several decades.\nThey have all been developed and tested using well-established toolchains (programming languages, compilers, linkers, profilers, debuggers, etc.), and rely on multiple services provided by modern operating systems (memory management, multi-tasking, file systems, networking, etc.)."}),"\n",(0,a.jsx)(t.p,{children:"Smart contracts are developed using ad-hoc toolchains, and run directly on top of custom virtual machines, without the support of an underlying operating system.\nThis arrangement deprives developers of the tools of their trade, severely reduces their expressive power, and consequently decimates their productivity."}),"\n",(0,a.jsxs)(t.p,{children:["In contrast, Cartesi Machines are based on a proven platform: ",(0,a.jsx)(t.a,{href:"https://riscv.org/",children:"RISC-V"}),".\nRISC-V was born of research in academia at UC Berkeley.\nIt is now maintained by its own independent foundation.\nUnlike many of its academic counterparts, it is important to keep in mind that RISC-V is not a toy architecture.\nIt is suitable for direct native hardware implementation, which is indeed currently commercialized by a large (and ever-increasing) number of ",(0,a.jsx)(t.a,{href:"https://en.wikipedia.org/wiki/RISC-V#Implementations",children:"vendors"}),".\nThis means that, in the future, Cartesi will not be limited to emulation or binary translation off-chain.\nThe RISC-V platform is supported by a vibrant community of developers.\nTheir efforts have produced an extensive software infrastructure, most notably ports of the Linux Operating System and the GNU toolchain."]}),"\n",(0,a.jsx)(t.p,{children:"By moving key parts of their dApp logic to run inside Cartesi Machines, but on top of the Linux Operating System, developers are isolated not only from the limitations and idiosyncrasies of specific blockchains, but also from irrelevant details of the Cartesi Machine architecture itself.\nThey regain access to all the tools they have come to rely on when writing applications."}),"\n",(0,a.jsx)(t.p,{children:"This is Cartesi's contribution to empowering dApp developers to express their creativity unimpeded, and to boost their productivity."}),"\n",(0,a.jsx)(t.h2,{id:"whats-in-a-machine",children:"What's in a machine"}),"\n",(0,a.jsxs)(t.p,{children:["All the components needed to create and run Cartesi Machines are distributed in the ",(0,a.jsx)(t.a,{href:"http://www.github.com/cartesi/machine-emulator-sdk",children:"Emulator SDK"}),"."]}),"\n",(0,a.jsxs)(t.p,{children:["Cartesi Machines are separated into a processor and a board.\nThe processor performs the computations, executing the traditional fetch-execute loop while maintaining a variety of registers.\nThe board defines the surrounding environment with an assortment of memories (ROM, RAM, flash drives, memory ranges) and a number of devices.\nMemories and devices are mapped to the 64-bit physical address space of the Cartesi Machine.\nThe amount of RAM, as well as the number, length, and position of the flash drives and memory ranges in the address space can be chosen according to the needs of each particular application.\nThe Cartesi Machine emulator is a program that carefully implements the Cartesi Machine architecture so that its executions are reproducible.\nIt can be built in the ",(0,a.jsx)(t.code,{children:"/emulator"})," directory of the Emulator SDK."]}),"\n",(0,a.jsxs)(t.p,{children:["The initialization of a Cartesi Machine loads a ROM image, a RAM image, and a root file-system (as a flash drive) from regular files in the host file-system.\nExecution starts from the ROM image, which contains a simple program that creates a description of the machine organization for the Linux kernel.\nThe ROM image ",(0,a.jsx)(t.code,{children:"rom.bin"})," can be built in the ",(0,a.jsx)(t.code,{children:"rom/"})," directory in the Emulator SDK.\nThe Linux kernel itself resides in the RAM image ",(0,a.jsx)(t.code,{children:"linux.bin"}),", built in the ",(0,a.jsx)(t.code,{children:"kernel/"})," directory in the Emulator SDK.\nAfter it is done with its own initialization, the Linux kernel cedes control to the ",(0,a.jsx)(t.code,{children:"/sbin/init"})," program in the root file-system.\nThe root file-system ",(0,a.jsx)(t.code,{children:"rootfs.ext2"})," contains all the data files and programs that make up an embedded Linux distribution.\nIt can be built in the ",(0,a.jsx)(t.code,{children:"fs/"})," directory in the Emulator SDK.\nThe components of the target application can reside in the root file-system itself, or in their own, separate file-systems.\nThe emulator can be instructed to execute whatever command is necessary to start the target application.\nFor a complete description of the Cartesi Machine architecture and the boot process, see the documentation for ",(0,a.jsx)(t.a,{href:"/docs/pr-preview/pr-303/cartesi-machine/target/",children:"the target perspective"}),"."]}),"\n",(0,a.jsxs)(t.p,{children:["There are two distinct modes of operation.\nIn the first mode, a Cartesi Machine is initialized and tasked to run a target application until the machine ",(0,a.jsx)(t.em,{children:"halts"}),".\nInputs for the target application can be provided as additional flash drives.\nLikewise, outputs can be sent to their own flash drives.\n(These drives can contain entire file-systems or can contain raw data.)\nOutputs are only available to the host after the machine halts.\nOnce it halts, the machine cannot perform any additional computations."]}),"\n",(0,a.jsxs)(t.p,{children:["In the second mode of operation, the target application runs in a loop.\nIn each iteration, it obtains a request carrying an input, performs any necessary computations to service the request, and produces a number of responses.\nAfter producing each response, the target application asks the machine to ",(0,a.jsx)(t.em,{children:"yield"})," control back to the host.\nThe host extracts the response and ",(0,a.jsx)(t.em,{children:"resumes"})," the machine.\nWhen done with a given input, the target application once again asks the machine to yield control back to the host.\nThe host then prepares the input for the next request, and ",(0,a.jsx)(t.em,{children:"resumes"})," the machine so the target application can service the next request in a new iteration of its loop.\nInputs and responses are transferred in special memory ranges (",(0,a.jsx)(t.em,{children:"rollup"})," memory ranges).\nWhatever state changes happen during the processing of a request will remain in effect when the next request is processed.\nIndeed, this is much like a server in which the target application can interact with the outside world.\nWe say that a Cartesi Machine operating in this mode is a ",(0,a.jsx)(t.em,{children:"Rolling Cartesi Machine"}),"."]}),"\n",(0,a.jsx)(t.h3,{id:"rolling-cartesi-machines-and-cartesi-rollups",children:"Rolling Cartesi Machines and Cartesi Rollups"}),"\n",(0,a.jsxs)(t.p,{children:["The stringent demands of reproducibility prevent a Cartesi Machine from communicating ",(0,a.jsx)(t.em,{children:"directly"})," with the outside world.\nIndeed, if two parties were to run the same Cartesi Machine and then disagree on the data each instance independently obtained from a network connection, there would be no way to settle their dispute.\nInstead, Rolling Cartesi Machines communicate with the outside world under controlled conditions, through ",(0,a.jsx)(t.em,{children:"Cartesi Rollups"}),"."]}),"\n",(0,a.jsx)(t.p,{children:"In a nutshell, Cartesi Rollups uses the blockchain to maintain a public record of requests made to advance the state of a Rolling Cartesi Machine.\nBoth the order and the inputs carried by these requests are recorded and made available in an indisputable fashion.\nSince Cartesi Machines are deterministic, and since the inputs are agreed upon, the state of a Rolling Cartesi Machine can be advanced in a well-defined way, always producing the same set of responses, no matter who runs it."}),"\n",(0,a.jsxs)(t.p,{children:["Advancing the state of a Rolling Cartesi Machine can produce four types of response: ",(0,a.jsx)(t.em,{children:"vouchers"}),", ",(0,a.jsx)(t.em,{children:"notices"}),", ",(0,a.jsx)(t.em,{children:"reports"}),", and\n",(0,a.jsx)(t.em,{children:"exceptions"}),".\nVouchers allow a Rolling Cartesi Machine to interact back with the blockchain.\nA voucher issued by the target application may, for example, grant a user the right to withdraw tokens locked into a custodial smart contract.\nNotices are used to register noteworthy changes to the state of the target application.\nA notice may be issued, for example, announcing the demise of a character in a game.\nDisputes over the fact that a voucher or notice has been generated while advancing the state of a Rolling Cartesi Machine can be settled by Cartesi Rollups.\nReports, in contrast, are used to output any data that is irrelevant to the blockchain.\nA report may, for example, provide diagnostic information on the reasons why an input has been rejected.\nFinally, an exception is used to signal an irrecoverable error encountered by the target application."]}),"\n",(0,a.jsx)(t.p,{children:"It is also possible to inspect the state of a local Rolling Cartesi Machine, without modifying it.\nState inspection produces only reports and exceptions."}),"\n",(0,a.jsx)(t.h2,{id:"documentation",children:"Documentation"}),"\n",(0,a.jsx)(t.p,{children:"Cartesi Machines can be seen from 3 different perspectives:"}),"\n",(0,a.jsxs)(t.ul,{children:["\n",(0,a.jsxs)(t.li,{children:[(0,a.jsx)(t.em,{children:"The host perspective"})," \u2014\nThis is the environment right outside the Cartesi Machine emulator.\nIt is most relevant to developers setting up Cartesi Machines, running them, or manipulating their contents.\nIt includes the emulator's API in all its flavors: C, C++, Lua, gRPC, and the command-line interface;"]}),"\n",(0,a.jsx)(t.li,{children:"_The target perspective _ \u2014\nThis is the environment inside the Cartesi Machine.\nIt encompasses Cartesi's particular flavor of the RISC-V architecture, as well as the organization of the embedded Linux Operating System that runs on top of it.\nIt is most relevant to programmers responsible for the dApp components that run off-chain but must be verifiable.\nThe cross-compiling toolchain, and the tools used to build the Linux kernel and the embedded Linux root file-systems are also important from this perspective, even though they are used in the host;"}),"\n",(0,a.jsxs)(t.li,{children:[(0,a.jsx)(t.em,{children:"The blockchain perspective"})," \u2014\nThis is the view smart contracts have of Cartesi Machines.\nIt consists almost exclusively of the manipulation of cryptographic hashes of the state of Cartesi Machines and parts thereof.\nIn particular, using only hash operations, the blockchain can verify assertions concerning the contents of the state, and can obtain the state hash that results from modifications to the state (including the execution of RISC-V instructions)."]}),"\n"]}),"\n",(0,a.jsx)(t.p,{children:"As with every computer, the level of knowledge required to interact with Cartesi Machines depends on the nature of the application being created.\nSimple applications will require target developers to code a few scripts invoking pre-installed software components, require host developers to simply fill out a configuration file specifying the location of the components needed to build a Cartesi Machine, and require blockchain developers to simply instantiate one of the high-level contracts provided by Cartesi.\nAt the other extreme are the developers working inside Cartesi, who regularly write, build, and deploy custom software components to run in the target, or even change the Linux kernel to support Cartesi-specific devices. Additionally, these developers programmatically control the creation and execution of Cartesi Machines in the host, and must also understand and use the hash-based state manipulation primitives the blockchain needs."}),"\n",(0,a.jsx)(t.p,{children:"Although Cartesi's goal is to shield platform users from as much complexity as possible, there is value in making information available to the greatest feasible extent. To that end, this documentation of Cartesi Machines aims to provide enough information to cover all 3 perspectives, at all depths of understanding."})]})}function d(e={}){const{wrapper:t}={...(0,s.R)(),...e.components};return t?(0,a.jsx)(t,{...e,children:(0,a.jsx)(l,{...e})}):l(e)}},28453:(e,t,n)=>{n.d(t,{R:()=>o,x:()=>r});var i=n(96540);const a={},s=i.createContext(a);function o(e){const t=i.useContext(s);return i.useMemo((function(){return"function"==typeof e?e(t):{...t,...e}}),[t,e])}function r(e){let t;return t=e.disableParentContext?"function"==typeof e.components?e.components(a):e.components||a:o(e.components),i.createElement(s.Provider,{value:t},e.children)}}}]);